public final class VfxFeedbackChecks {static int n;static void c(boolean x){n++;if(!x)throw new AssertionError("check "+n);}public static void main(String[] args){VfxFeedback f=new VfxFeedback();f.sample(20,4,20,true,0,1);c(f.trauma==0);f.sample(20,2,20,true,0,1);c(f.trauma>0);double t=f.trauma;f.sample(20,3,20,true,0,1);c(f.trauma<t);f.clear();f.sample(20,0,20,false,8,1);c(f.trauma==0);f.sample(20,0,20,true,0,1);c(f.trauma>0);f.clear();f.sample(20,0,20,true,0,1);c(f.trauma==0&&f.punch==0);f.acceptedSwing(false);c(f.punch==.3);f.acceptedSwing(true);c(f.punch>.89&&f.punch<.91);for(int i=0;i<100;i++)f.acceptedSwing(true);c(f.punch==1);f.sample(20,0,20,true,0,1000);c(f.punch>.12&&f.punch<.14);f.sample(Double.NaN,0,20,true,0,1);c(f.trauma==0&&f.punch==0);VoxelRules.Frames q=new VoxelRules.Frames();q.frame(2);q.push(20);c(q.globalCube());q.push(20);c(q.globalCube());q.pop();c(!q.globalCube()&&q.globalUsed()==2&&q.globalSkipped()==1);q.frame(1);c(q.globalCube()&&!q.globalCube());q.pop();q.frame(-1);c(!q.globalCube());q.frame(Integer.MAX_VALUE);for(int i=0;i<9000;i++)c(q.globalCube());c(!q.globalCube());System.out.println("VfxFeedbackChecks: "+n+" PASS");}}
